import { useState, useEffect, useCallback } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getActiveTimer } from '../api/timeTracker.api';

/**
 * Aktif timer hook'u.
 * Backend'den startedAt al─▒r, setInterval ile canl─▒ saya├ğ ├ğal─▒┼şt─▒r─▒r.
 * Date.now() sadece elapsed s├╝re hesab─▒ i├ğin kullan─▒l─▒r, timestamp ├╝retmez.
 */
export function useActiveTimer() {
    const [elapsed, setElapsed] = useState(0);

    const query = useQuery({
        queryKey: ['active-timer'],
        queryFn: getActiveTimer,
    });

    const startedAt = query.data?.startedAt;
    const isActive = !!query.data && query.data.status === 'ACTIVE';

    const calcElapsed = useCallback(() => {
        if (!startedAt) return 0;
        return Math.floor((Date.now() - new Date(startedAt).getTime()) / 1_000);
    }, [startedAt]);

    useEffect(() => {
        if (!isActive || !startedAt) {
            setElapsed(0);
            return;
        }

        setElapsed(calcElapsed());

        const interval = setInterval(() => {
            setElapsed(calcElapsed());
        }, 1_000);

        return () => clearInterval(interval);
    }, [isActive, startedAt, calcElapsed]);

    return {
        ...query,
        timer: query.data,
        isActive,
        elapsed,
    };
}

