import { http, HttpResponse } from 'msw';
import { MOCK_CLIENTS } from '../data/clients';

const getRoleFromRequest = (request: Request) => {
    const auth = request.headers.get('Authorization');
    if (!auth) return null;
    const payload = JSON.parse(atob(auth.replace('Bearer ', '')));
    return payload;
};

export const clientHandlers = [

    http.get('http://localhost:3500/api/clients', ({ request }) => {
        const payload = getRoleFromRequest(request);
        const url = new URL(request.url);
        const page = parseInt(url.searchParams.get('page') || '1');
        const limit = parseInt(url.searchParams.get('limit') || '20');
        const type = url.searchParams.get('type');
        const status = url.searchParams.get('status');
        const search = url.searchParams.get('search')?.toLowerCase();

        let data = [...MOCK_CLIENTS];

        // ACCOUNT_MGR isolation
        if (payload?.role === 'ACCOUNT_MGR') {
            data = data.filter(c => c.assignedTo === payload.userId);
        }

        if (type) data = data.filter(c => c.type === type);
        if (status) data = data.filter(c => c.status === status);
        if (search) data = data.filter(c => c.name.toLowerCase().includes(search) || c.email.toLowerCase().includes(search));

        const total = data.length;
        const paginatedData = data.slice((page - 1) * limit, page * limit);

        return HttpResponse.json({ data: paginatedData, total, page, limit });
    }),

    http.get('http://localhost:3500/api/clients/:id', ({ params, request }) => {
        const payload = getRoleFromRequest(request);
        const client = MOCK_CLIENTS.find(c => c.id === params.id);
        if (!client) return HttpResponse.json({ message: 'Bulunamad─▒' }, { status: 404 });
        return HttpResponse.json(client);
    }),

    http.post('http://localhost:3500/api/clients', async ({ request }) => {
        const body = await request.json() as any;
        const newClient = { id: `C${Date.now()}`, ...body, createdAt: new Date().toISOString() };
        MOCK_CLIENTS.push(newClient);
        return HttpResponse.json(newClient, { status: 201 });
    }),

    http.patch('http://localhost:3500/api/clients/:id', async ({ params, request }) => {
        const body = await request.json() as any;
