import { http, HttpResponse } from 'msw';
import { MOCK_PERSONNEL } from '../data/personnel';

// Token'dan rol ├ğek
const getRoleFromRequest = (request: Request) => {
    const auth = request.headers.get('Authorization');
    if (!auth) return null;
    const payload = JSON.parse(atob(auth.replace('Bearer ', '')));
    return payload;
};

export const personnelHandlers = [

    // GET /personnel ÔÇö sayfalama + filtreleme + rol bazl─▒
    http.get('http://localhost:3500/api/personnel', ({ request }) => {
        const payload = getRoleFromRequest(request);
        const url = new URL(request.url);
        const page = parseInt(url.searchParams.get('page') || '1');
        const limit = parseInt(url.searchParams.get('limit') || '20');
        const dept = url.searchParams.get('dept');
        const role = url.searchParams.get('role');
        const status = url.searchParams.get('status');
        const search = url.searchParams.get('search')?.toLowerCase();

        let data = [...MOCK_PERSONNEL];

        // MANAGER sadece kendi departman─▒n─▒ g├Âr├╝r
        if (payload?.role === 'MANAGER') data = data.filter(p => p.department === payload.department);
        if (dept) data = data.filter(p => p.department === dept);
        if (role) data = data.filter(p => p.role === role);
        if (status) data = data.filter(p => p.status === status);
        if (search) data = data.filter(p => p.name.toLowerCase().includes(search) || p.email.toLowerCase().includes(search));

        // Maa┼ş: CEO ve ACCOUNTING d─▒┼ş─▒nda g├Ânderme
        const canSeeSalary = ['CEO', 'ACCOUNTING'].includes(payload?.role);
        if (!canSeeSalary) data = data.map(({ salary, ...rest }) => rest);

        const total = data.length;
        const paginatedData = data.slice((page - 1) * limit, page * limit);

        return HttpResponse.json({ data: paginatedData, total, page, limit });
    }),

    // GET /personnel/:id
    http.get('http://localhost:3500/api/personnel/:id', ({ params, request }) => {
        const payload = getRoleFromRequest(request);
        const person = MOCK_PERSONNEL.find(p => p.id === params.id);
        if (!person) return HttpResponse.json({ message: 'Bulunamad─▒' }, { status: 404 });
        const canSeeSalary = ['CEO', 'ACCOUNTING'].includes(payload?.role);
        const { salary, ...rest } = person;
        return HttpResponse.json(canSeeSalary ? person : rest);
    }),

    // POST /personnel
    http.post('http://localhost:3500/api/personnel', async ({ request }) => {
        const body = await request.json() as any;
        const newPerson = { id: String(Date.now()), ...body, createdAt: new Date().toISOString() };
        MOCK_PERSONNEL.push(newPerson);
        return HttpResponse.json(newPerson, { status: 201 });
    }),

    // PATCH /personnel/:id
    http.patch('http://localhost:3500/api/personnel/:id', async ({ params, request }) => {
        const body = await request.json() as any;
        const index = MOCK_PERSONNEL.findIndex(p => p.id === params.id);
        if (index === -1) return HttpResponse.json({ message: 'Bulunamad─▒' }, { status: 404 });
        MOCK_PERSONNEL[index] = { ...MOCK_PERSONNEL[index], ...body };
        return HttpResponse.json(MOCK_PERSONNEL[index]);
    }),

    // DELETE /personnel/:id
    http.delete('http://localhost:3500/api/personnel/:id', ({ params }) => {
        const index = MOCK_PERSONNEL.findIndex(p => p.id === params.id);
        if (index === -1) return HttpResponse.json({ message: 'Bulunamad─▒' }, { status: 404 });
        MOCK_PERSONNEL.splice(index, 1);
        return HttpResponse.json({ message: 'Silindi' });
    }),

    // GET /personnel/export
    http.get('http://localhost:3500/api/personnel/export', () => {
        // Ger├ğek export'ta blob d├Âner, mock'ta basit JSON yeterli
        return HttpResponse.json(MOCK_PERSONNEL);
    }),
];

