import { http, HttpResponse } from 'msw';
import { MOCK_TIME_ENTRIES, MOCK_ACTIVE_ENTRY } from '../data/timeTracker';

let activeEntry: any = { ...MOCK_ACTIVE_ENTRY };

export const timeTrackerHandlers = [

    // GET /time-tracker/active
    http.get('http://localhost:3500/api/time-tracker/active', () => {
        return HttpResponse.json(activeEntry);
    }),

    // POST /time-tracker/start ÔÇö startedAt backend'den gelir
    http.post('http://localhost:3500/api/time-tracker/start', async ({ request }) => {
        if (activeEntry) {
            return HttpResponse.json({ message: 'Zaten aktif bir kay─▒t var' }, { status: 400 });
        }
        const body = await request.json() as any;
        activeEntry = {
            id: String(Date.now()),
            projectId: body.projectId,
            description: body.description,
            startedAt: new Date().toISOString(), // ÔåÉ server timestamp sim├╝lasyonu
            endedAt: null,
        };
        return HttpResponse.json(activeEntry, { status: 201 });
    }),

    // POST /time-tracker/stop/:id
    http.post('http://localhost:3500/api/time-tracker/stop/:id', ({ params }) => {
        if (!activeEntry || activeEntry.id !== params.id) {
            return HttpResponse.json({ message: 'Aktif kay─▒t bulunamad─▒' }, { status: 404 });
        }
        const stopped = { ...activeEntry, endedAt: new Date().toISOString() };
        MOCK_TIME_ENTRIES.unshift(stopped);
        activeEntry = null;
        return HttpResponse.json(stopped);
    }),

    // POST /time-tracker/cancel/:id
    http.post('http://localhost:3500/api/time-tracker/cancel/:id', ({ params }) => {
        if (!activeEntry || activeEntry.id !== params.id) {
            return HttpResponse.json({ message: 'Aktif kay─▒t bulunamad─▒' }, { status: 404 });
        }
        activeEntry = null;
        return HttpResponse.json({ message: 'Kay─▒t iptal edildi' });
    }),

    // GET /time-tracker
    http.get('http://localhost:3500/api/time-tracker', ({ request }) => {
        const url = new URL(request.url);
        const page = parseInt(url.searchParams.get('page') || '1');
        const limit = parseInt(url.searchParams.get('limit') || '20');
        const total = MOCK_TIME_ENTRIES.length;
        const data = MOCK_TIME_ENTRIES.slice((page - 1) * limit, page * limit);
        return HttpResponse.json({ data, total, page, limit });
    }),
];
